INSERT INTO cases (case_number, case_title, case_type_id, status, priority, jurisdiction_location_id, description, opened_at, closed_at, created_by) VALUES
    ('CASE-2026-001', 'Corporate Cyber Fraud Investigation', 3, 'under_investigation', 'high', 3, 'Suspected internal financial fraud at a mid-sized manufacturing firm, involving falsified vendor invoices and unauthorized fund transfers routed through compromised finance-department workstations.', '2026-01-05 09:00:00', NULL, 1),
    ('CASE-2026-002', 'Ransomware Attack on Regional Logistics Network', 4, 'open', 'critical', 6, 'A logistics company''s order-management server and several workstations were encrypted overnight; a ransom note references a double-extortion threat to leak exfiltrated shipment data.', '2026-01-11 09:00:00', NULL, 5),
    ('CASE-2026-003', 'Data Exfiltration by Former IT Administrator', 2, 'closed', 'medium', 3, 'A departing IT administrator is alleged to have copied customer databases to a personal external drive in the two weeks prior to resignation.', '2025-11-26 09:00:00', '2026-01-02 09:00:00', 4),
    ('CASE-2026-004', 'Phishing Campaign Targeting Municipal Finance Office', 1, 'pending_review', 'medium', 6, 'A spear-phishing email impersonating a vendor led to a municipal finance clerk disclosing portal credentials, resulting in a fraudulent payment redirection attempt.', '2026-01-15 09:00:00', NULL, 10),
    ('CASE-2026-005', 'Cryptocurrency Wallet Theft Investigation', 3, 'archived', 'low', 3, 'A private individual''s cryptocurrency wallet was drained following a compromised seed-phrase backup stored in an unencrypted note on a personal laptop.', '2025-10-27 09:00:00', '2025-12-16 09:00:00', 1);
