    ('EVD-2026-001', 1, 1, 1, 'Full physical disk image of the seized Samsung Galaxy S23 (SNCF10021A) belonging to suspect Ramesh Chandran.', '/evidence/case-001/EVD-2026-001.dd', 128849018880, 'physical_extraction', 2, '2026-01-05 11:00:00', 2, 'intact'),
    ('EVD-2026-002', 1, 2, 1, 'Forensic disk image of the Dell Latitude 5540 laptop assigned to the finance department manager.', '/evidence/case-001/EVD-2026-002.E01', 549755813888, 'physical_extraction', 2, '2026-01-05 11:30:00', 2, 'intact'),
    ('EVD-2026-003', 1, 2, 2, 'Live RAM capture taken from the Dell Latitude 5540 laptop prior to shutdown.', '/evidence/case-001/EVD-2026-003.mem', 17179869184, 'logical_extraction', 2, '2026-01-05 11:45:00', 2, 'intact'),
    ('EVD-2026-004', 1, 3, 3, 'Extracted Windows Event Logs from the EliteDesk 800 workstation covering the fraud window.', '/evidence/case-001/EVD-2026-004-eventlogs.zip', 47185920, 'logical_extraction', 1, '2026-01-05 12:00:00', 2, 'intact'),
    ('EVD-2026-005', 1, NULL, 4, 'Photographic documentation of the seizure scene at the finance department office.', '/evidence/case-001/EVD-2026-005-photos.zip', 62914560, 'manual_documentation', 1, '2026-01-05 10:00:00', 2, 'intact'),
    ('EVD-2026-006', 1, 4, 5, 'Scanned set of falsified vendor invoices recovered from the external hard disk drive.', '/evidence/case-001/EVD-2026-006-invoices.pdf', 18874368, 'manual_documentation', 4, '2026-01-05 13:00:00', 2, 'intact'),
    ('EVD-2026-007', 1, 3, 7, 'Exported Outlook mailbox archive from the EliteDesk workstation covering vendor correspondence.', '/evidence/case-001/EVD-2026-007-mailbox.pst', 2147483648, 'logical_extraction', 2, '2026-01-05 12:30:00', 2, 'intact'),
    ('EVD-2026-008', 1, NULL, 6, 'Network traffic capture from the finance department VLAN during the suspected transfer window.', '/evidence/case-001/EVD-2026-008-capture.pcap', 314572800, 'network_capture', 1, '2026-01-05 14:00:00', 2, 'intact'),
    ('EVD-2026-009', 2, 5, 1, 'Forensic image of the PowerEdge R440 order-management server disk array.', '/evidence/case-002/EVD-2026-009.E01', 2199023255552, 'physical_extraction', 6, '2026-01-11 11:00:00', 8, 'intact'),
    ('EVD-2026-010', 2, 5, 2, 'RAM capture of the compromised order-management server prior to isolation.', '/evidence/case-002/EVD-2026-010.mem', 34359738368, 'logical_extraction', 6, '2026-01-11 11:15:00', 8, 'under_verification'),
    ('EVD-2026-011', 2, 7, 3, 'Router configuration and connection logs extracted from the Cisco ISR 4331.', '/evidence/case-002/EVD-2026-011-router.log', 8388608, 'logical_extraction', 5, '2026-01-11 12:00:00', 8, 'intact'),
    ('EVD-2026-012', 2, NULL, 6, 'Full packet capture of the logistics network during the ransomware encryption event.', '/evidence/case-002/EVD-2026-012.pcap', 943718400, 'network_capture', 5, '2026-01-11 13:00:00', 8, 'intact'),
    ('EVD-2026-013', 2, 6, 1, 'Disk image of the first workstation observed encrypted, belonging to the IT operations head.', '/evidence/case-002/EVD-2026-013.E01', 549755813888, 'physical_extraction', 6, '2026-01-11 11:30:00', 8, 'intact'),
    ('EVD-2026-014', 2, NULL, 5, 'Scanned copy of the printed ransom note left on affected workstation desktops.', '/evidence/case-002/EVD-2026-014-ransomnote.pdf', 2097152, 'manual_documentation', 5, '2026-01-11 14:00:00', 8, 'intact'),
    ('EVD-2026-015', 3, 8, 1, 'Disk image of the departing IT administrator''s OptiPlex 7010 workstation.', '/evidence/case-003/EVD-2026-015.E01', 1099511627776, 'physical_extraction', 9, '2025-11-26 10:00:00', 2, 'intact'),
    ('EVD-2026-016', 3, 8, 3, 'Database access and export logs recovered from the OptiPlex workstation.', '/evidence/case-003/EVD-2026-016-dblogs.zip', 15728640, 'logical_extraction', 9, '2025-11-26 10:30:00', 2, 'intact'),
    ('EVD-2026-017', 3, 9, 1, 'Disk image of the SanDisk USB flash drive seized from the administrator''s desk.', '/evidence/case-003/EVD-2026-017.dd', 128974848, 'physical_extraction', 9, '2025-11-26 11:00:00', 2, 'compromised'),
    ('EVD-2026-018', 3, NULL, 5, 'Scanned HR resignation and exit-interview paperwork referenced in the case timeline.', '/evidence/case-003/EVD-2026-018-hrdocs.pdf', 5242880, 'manual_documentation', 4, '2025-11-26 12:00:00', 2, 'intact'),
