INSERT INTO evidence_examinations (evidence_id, tool_id, examiner_id, examination_type, started_at, completed_at, findings_summary, examination_status) VALUES
    (1, 6, 2, 'data_recovery', '2026-01-06 09:00:00', '2026-01-06 15:00:00', 'Recovered deleted messaging app data referencing an external vendor account under investigation.', 'completed'),
    (2, 1, 2, 'static_analysis', '2026-01-06 11:00:00', '2026-01-06 18:00:00', 'File-system timeline shows batch creation of invoice PDFs outside normal business hours.', 'completed'),
    (3, 5, 4, 'dynamic_analysis', '2026-01-06 10:00:00', NULL, 'Memory analysis in progress; reviewing process list for unauthorized remote-access tooling.', 'in_progress'),
    (7, 8, 2, 'timeline_analysis', '2026-01-07 09:00:00', '2026-01-07 14:00:00', 'Email correspondence timeline corroborates invoice submission dates from three flagged vendor accounts.', 'peer_reviewed'),
    (9, 2, 6, 'static_analysis', '2026-01-12 09:00:00', '2026-01-12 17:00:00', 'Identified ransomware binary and lateral-movement artifacts consistent with a known ransomware family.', 'completed'),
    (10, 5, 6, 'dynamic_analysis', '2026-01-12 10:00:00', '2026-01-12 19:00:00', 'Volatile memory confirms an active encryption process and an outbound C2 connection at time of capture.', 'completed'),
    (11, 4, 5, 'network_analysis', '2026-01-12 11:00:00', '2026-01-12 16:00:00', 'Router logs show an unusual outbound connection shortly before the encryption event began.', 'completed'),
    (12, 4, 5, 'network_analysis', '2026-01-12 12:00:00', NULL, 'Deep packet inspection of the capture ongoing to map the full extent of data exfiltration.', 'in_progress'),
    (13, 6, 6, 'file_carving', '2026-01-13 09:00:00', '2026-01-13 15:00:00', 'Carved partially-encrypted files to recover fragments of the pre-encryption directory structure.', 'completed'),
    (15, 3, 9, 'static_analysis', '2025-11-27 09:00:00', '2025-11-27 16:00:00', 'File access timestamps show bulk database export activity in the two weeks before resignation.', 'completed'),
    (17, 3, 9, 'data_recovery', '2025-11-27 17:00:00', '2025-11-28 09:00:00', 'Recovered previously deleted export archive from unallocated space on the USB drive.', 'peer_reviewed'),
    (19, 7, 9, 'static_analysis', '2025-11-28 09:00:00', '2025-11-29 09:00:00', 'Mailbox review identifies correspondence with a personal email address matching the export window.', 'completed'),
    (16, 1, 4, 'timeline_analysis', '2025-11-29 09:00:00', '2025-11-30 09:00:00', 'Cross-referenced database logs against badge-access records to confirm after-hours presence.', 'completed'),
    (21, 6, 3, 'data_recovery', '2026-01-16 09:00:00', '2026-01-16 14:00:00', 'Extracted sent-message history confirming the phishing email was composed and sent from this device.', 'completed'),
    (22, 8, 3, 'static_analysis', '2026-01-16 10:00:00', '2026-01-16 15:00:00', 'Mailbox headers confirm domain spoofing consistent with the vendor-impersonation phishing template.', 'completed'),
    (23, 7, 10, 'static_analysis', '2026-01-16 11:00:00', NULL, 'Reviewing cached browser sessions for evidence of the fraudulent payment portal.', 'in_progress'),
    (25, 4, 3, 'network_analysis', '2026-01-17 09:00:00', '2026-01-17 13:00:00', 'Traffic capture confirms the finance office workstation submitted credentials to the spoofed portal.', 'completed'),
    (26, 6, 1, 'data_recovery', '2025-10-28 09:00:00', '2025-10-28 14:00:00', 'Recovered wallet application session data confirming the device used to authorize the transfer.', 'completed'),
    (27, 1, 7, 'static_analysis', '2025-10-28 10:00:00', '2025-10-28 18:00:00', 'Located an unencrypted notes file containing what appears to be the wallet seed phrase.', 'completed'),
    (28, 5, 7, 'dynamic_analysis', '2025-10-28 11:00:00', '2025-10-28 15:00:00', 'Memory artifacts consistent with clipboard-hijacking malware active at the time of the transfer.', 'peer_reviewed');
