-- =====================================================================
-- FORGE-X : Forensic Operations, Records, Governance & Evidence Exchange
-- File   : 09_seed_data.sql
-- Purpose: Realistic, fully self-consistent demo/test dataset covering
--          every table and the complete evidence lifecycle, including a
--          flagship case (CASE-2026-001) with rich narrative detail.
-- Depends: 01_create_database.sql, 02_tables.sql, 03_constraints.sql,
--          04_indexes.sql must already have run.
--
-- GENERATION METHOD
--   This file was generated by a small deterministic Python script
--   (scripts/generate_seed_data.py) rather than typed by hand, so that
--   ~450+ rows across 21 interdependent tables stay perfectly
--   referentially consistent (every FK value is guaranteed to exist)
--   while still reading as realistic, narratively coherent case data —
--   not Lorem-Ipsum filler. No randomness is used: every value is
--   picked deterministically from realistic-but-fictional pools, so
--   the output is 100% reproducible.
--
-- FICTIONAL DATA NOTICE
--   All names, badge numbers, national ID numbers, IP addresses, device
--   serials/IMEIs, and case content below are entirely fictional and
--   were constructed for this demo. No real person's data is used.
-- =====================================================================

USE forge_x;

-- Defensive: ensures THIS session sends/receives utf8mb4 regardless of
-- how the client was invoked (protects against a classic gotcha: running
-- `mysql -u root < this_file.sql` without --default-character-set=utf8mb4
-- silently corrupts any non-ASCII literal in this file via latin1
-- misinterpretation at write time -- discovered and fixed during Step 6
-- backend integration testing).
SET NAMES utf8mb4;

SET SESSION sql_mode = 'STRICT_ALL_TABLES,NO_ZERO_DATE,NO_ZERO_IN_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SET time_zone = '+00:00';

START TRANSACTION;
