-- 15. evidence_hashes
-- Uses MySQL's native SHA2() to derive a realistic, valid 64-char hex
-- hash per evidence item directly from its evidence_number + acquisition
-- timestamp, so every row is guaranteed unique and passes the
-- chk_evidence_hashes_length CHECK constraint (>= 32 chars) trivially.
-- =====================================================================
SELECT
    e.evidence_id,
    'SHA256',
    SHA2(CONCAT(e.evidence_number, '|original|', e.collected_at), 256),
    e.collected_by,
    e.collected_at + INTERVAL 15 MINUTE,
    1
FROM evidence e;
-- Re-verification hashes for the flagship case's evidence (demonstrates
-- is_original = 0 and repeated integrity checks over time).
SELECT
    e.evidence_id,
    'SHA256',
    SHA2(CONCAT(e.evidence_number, '|reverify-30d|', e.collected_at), 256),
    e.collected_by,
    e.collected_at + INTERVAL 30 DAY,
    0
FROM evidence e
WHERE e.case_id = 1;
